/**
 * What a stage's units are, right now, from the persisted inputs alone.
 * `scalar` and `artifact_collection` always mint exactly unit `"0"`;
 * `fan_out` mints one unit per driver artifact (or per item of a
 * non-input `over` binding — repository provisioning fans out over run
 * context, which is why `malformed_driver_artifact.artifact_id` may be null).
 */
export const mintUnits = (contract: CompiledStageContract, inputs: StageInputSet, context: JsonValue): Result<readonly MintedUnit[], Contradiction> => {
  const materialization = contract.materialization;
  const environment: BindingEnvironment = { inputs, context, item: null };

  if (materialization.kind === "scalar") return finalizeMintedUnits(contract, inputs, [{ unit: { unit_id: "0" as UnitId, parameters: {}, depends_on: [] }, source_artifact_id: null }]);

  if (materialization.kind === "artifact_collections") {
    const members: JsonValue[] = [];
    let sourceId: ArtifactId | null = null;
    for (const production of materialization.productions) {
      sourceId ??= sourceArtifactId(production.over, inputs);
      const path = bindingPath(production.over);
      const over = resolveBindingValue(production.over, environment);
      if (!over.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: sourceId, path, detail: over.error.detail });
      if (!Array.isArray(over.value)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: sourceId, path, detail: `${materialization.kind}.over must resolve to an array` });
      for (const item of over.value) {
        const key = readJsonPointer(item, production.id_path);
        if (typeof key !== "string" || key.length === 0) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: sourceId,
          path: production.id_path, detail: `artifact collection key '${production.id_path}' must be a non-empty string` });
        members.push({ collection_key: key });
      }
    }
    return finalizeMintedUnits(contract, inputs, [{ unit: { unit_id: "0" as UnitId, parameters: members, depends_on: [] }, source_artifact_id: sourceId }]);
  }

  // fan_out — one pass over either source: the driver artifacts, or the items of a
  // non-input binding (repository provisioning fans out over run context).
  const spec: DriverItemSpec = { unit_id_path: materialization.unit_id_path, depends_on_path: materialization.depends_on_path };
  let items: readonly DriverItem[];
  if (materialization.over.from === "input") {
    items = selectDriverArtifacts(inputs, materialization.over.input_name).map((artifact) => ({ item: { unit_id: artifact.unit_id, artifact: artifact.body } as JsonValue, source_artifact_id: artifact.artifact_id }));
  } else {
    const over = resolveBindingValue(materialization.over, environment);
    if (!over.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: bindingPath(materialization.over), detail: over.error.detail });
    if (!Array.isArray(over.value)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: null, path: bindingPath(materialization.over), detail: `${materialization.kind}.over must resolve to an array` });
    items = over.value.map((item) => ({ item, source_artifact_id: null }));
  }
  const driverUnits: DriverUnit[] = [];
  const seen = new Set<string>();
  for (const { item, source_artifact_id } of items) {
    const parsed = parseDriverItem(item, spec);
    if (!parsed.ok) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: source_artifact_id, path: parsed.error.path, detail: parsed.error.detail });
    if (seen.has(parsed.value.unit_id)) return err({ kind: "malformed_driver_artifact", stage_key: contract.stage_key, artifact_id: source_artifact_id, path: spec.unit_id_path, detail: `duplicate unit_id '${parsed.value.unit_id}'` });
    seen.add(parsed.value.unit_id);
    driverUnits.push({ unit: parsed.value, source_artifact_id });
  }
  return finalizeMintedUnits(contract, inputs, driverUnits);
};
